                if (num < answer) {
                    answer = num;
                }
            }
        }

        // First digit from B, second from A
        for (int b : setB) {
            for (int a : setA) {
                int num = b * 10 + a;
                if (num < answer) {
                    answer = num;
                }
            }
        }

        System.out.println(answer);
    }
